 code=f'''import vail as h,time,resource,json,math
h.eval(0);mode={mode!r};n={n};parts={parts};size={size}
t=h.range_table(n,parts)
if mode=='nested':
 t=t.annotate(value=h.int64(t.idx))
 for level in range(size):
