 start=time.perf_counter();r=t.aggregate(h.struct(count=h.agg.count(),total=h.agg.sum(t.value)));elapsed=time.perf_counter()-start
 assert r.count==n and r.total==n*(n-1)//2*2**size;check=dict(count=r.count,total=r.total)
else:
 if mode=='computed':t=t.annotate(value=h.sum(h.range(size).map(lambda i:h.float64(t.idx+i)**2)))
 elif mode in ('wide','keyless'):t=t.annotate(value=h.range(size).map(lambda i:t.idx+i))
 else:t=t.annotate(value=h.scan.sum(t.idx),random=h.rand_unif(seed=71))
 if mode=='keyless':t=t.key_by()
 z=h.Table.multi_way_zip_join([t,t,t,t],'data','globals')
 start=time.perf_counter()
 if mode=='keyless':
  rows=z.collect();elapsed=time.perf_counter()-start;assert len(rows)==1 and all(x.value==list(range(size)) for x in rows[0].data);check=dict(count=1,width=len(rows[0].data[0].value))
 else:
  x=z.data[0].value[-1] if mode=='wide' else z.data[0].value
  y=z.data[3].value[-1] if mode=='wide' else z.data[3].value
  same=h.agg.all(x==y)
  if mode=='stateful':same=same & h.agg.all(z.data[0].random==z.data[3].random)
  r=z.aggregate(h.struct(count=h.agg.count(),total=h.agg.sum(x),same=same));elapsed=time.perf_counter()-start
  expected=n*(n-1)//2+n*(size-1) if mode=='wide' else size*n*(n-1)*(2*n-1)/6+2*n*(n-1)/2*size*(size-1)/2+n*size*(size-1)*(2*size-1)/6 if mode=='computed' else n*(n-1)*(n-2)//6
  assert r.count==n and r.same and math.isclose(r.total,expected,rel_tol=1e-12),(r,expected);check=dict(count=r.count,total=r.total,same=r.same)
print(json.dumps(dict(execution_seconds=elapsed,peak_rss_bytes=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss,check=check)))'''
