import os,sys,json,subprocess,tempfile,time
root='/Users/danielking/.codex/worktrees/412f/vail/vail';version=sys.argv[1];path='/tmp/vail-table-join-baseline' if version=='baseline' else root+'/python'
def disk_bytes(directory):
 total=0
 for base,ds,fs in os.walk(directory):
  for f in fs:
   try:total+=os.path.getsize(os.path.join(base,f))
   except FileNotFoundError:pass
 return total
results=[]
for n,width,action in [(4096,256,'head'),(16384,256,'head'),(4096,256,'full'),(16384,256,'full')]:
 code=f'''import vail as h,time,resource,json,gc,os
h.eval(0);n={n};width={width};action={action!r}
t=h.range_table(n,1);t=t.annotate(value=h.range(width).map(lambda i:t.idx+i))
z=h.Table.multi_way_zip_join([t,t],'data','globals')
start=time.perf_counter()
if action=='head':
 rows=z.head(1).collect();assert len(rows)==1 and all(x.value==list(range(width)) for x in rows[0].data);check={{'count':1,'width':len(rows[0].data[0].value)}}
else:
 r=z.aggregate(h.struct(count=h.agg.count(),total=h.agg.sum(z.data[0].value[-1]),same=h.agg.all(z.data[0].value==z.data[1].value)))
 assert r.count==n and r.total==n*(n-1)//2+n*(width-1) and r.same;check={{'count':r.count,'total':r.total,'same':r.same}}
elapsed=time.perf_counter()-start
del z,t;gc.collect()
remaining=sum(os.path.getsize(os.path.join(base,f)) for base,ds,fs in os.walk(os.environ['TMPDIR']) for f in fs)
print(json.dumps(dict(execution_seconds=elapsed,peak_rss_bytes=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss,tempfile_bytes_after_action_gc=remaining,check=check)))'''
 with tempfile.TemporaryDirectory() as d:
  p=subprocess.Popen([root+'/.venv/bin/python','-c',code],cwd='/tmp',env=dict(os.environ,PYTHONPATH=path,TMPDIR=d),stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
  peak=0;start=time.monotonic();timedout=False
  while p.poll() is None:
   peak=max(peak,disk_bytes(d))
   if time.monotonic()-start>30:p.kill();timedout=True;break
   time.sleep(.005)
  out,err=p.communicate();remaining=disk_bytes(d)
  r=dict(timeout_seconds=30) if timedout else json.loads(out) if not p.returncode else dict(error=err[-2000:])
  results.append(dict(version=version,n=n,width=width,partitions=1,action=action,peak_tempfile_bytes=peak,remaining_tempfile_bytes_after_exit=remaining,**r))
print(json.dumps(results,indent=2))
